// StackLens technology signatures.
//
// Each technology can be detected from any of these signals:
//   url        regex(es) tested against the page URL
//   html       regex(es) tested against the page markup
//   css        regex(es) tested against same-origin CSS rules
//   scriptSrc  regex(es) tested against <script src> URLs
//   resources  regex(es) tested against every loaded URL (scripts, styles, frames, fetch/XHR, images…)
//   meta       { metaName: pattern }       e.g. generator
//   headers    { headerName: pattern }     response headers of the main document
//   cookies    { cookieName: '' }          names only ("/regex/" keys allowed)
//   js         { 'global.path': pattern }  window globals ("prefix*" = any global starting with prefix)
//   dom        CSS selectors, or { selector, attr } to read a version from an attribute
//   probe      name of a built-in runtime probe (react, vue, svelte, serviceWorker)
//   implies    other technologies this one implies
//
// Pattern: '' (exists) | RegExp | { re, version: '\\1', confidence, caseSensitive }.
// Regexes are case-insensitive unless caseSensitive is set.
// Confidence defaults to 100; a technology's score is the capped sum of its matched patterns.

const V = { re: /^(.+)$/, version: '\\1' }; // the value itself is the version
const v = (re, confidence) => ({ re, version: '\\1', ...(confidence !== undefined && { confidence }) });
const c = (re, confidence) => ({ re, confidence });
const ex = (confidence) => ({ re: null, confidence }); // existence with custom confidence
const verOnly = { re: /^(.+)$/, version: '\\1', confidence: 0 }; // adds a version, never detects alone

